#include <algorithm>
#include <cctype>
#include <optional>
#include <string>
#include <utility>
#include <vector>

std::optional<int> fuzzyScore(const std::string& query, const std::string& candidate)
{
    auto low = [](char c) { return static_cast<char>(std::tolower(static_cast<unsigned char>(c))); };
    auto wordStart = [&](std::size_t i) { return i == 0 || std::string(" -_.").find(candidate[i - 1]) != std::string::npos; };
    int score{ 0 };
    std::size_t at{ 0 };
    long long previous{ -2 };
    for (char q : query)
    {
        while (at < candidate.size() && low(candidate[at]) != low(q)) ++at;
        if (at == candidate.size()) return std::nullopt;
        score += 1;
        if (wordStart(at)) score += 5;
        if (static_cast<long long>(at) == previous + 1) score += 3;
        previous = static_cast<long long>(at);
        ++at;
    }
    return score;
}

std::vector<std::string> rank(const std::string& query, const std::vector<std::string>& candidates)
{
    std::vector<std::pair<int, std::string>> scored;
    for (const std::string& c : candidates)
        if (const auto s{ fuzzyScore(query, c) }) scored.push_back({ *s, c });
    std::stable_sort(scored.begin(), scored.end(), [](const auto& a, const auto& b) { return a.first > b.first; });
    std::vector<std::string> out;
    for (auto& [s, c] : scored) out.push_back(c);
    return out;
}

unitTests:
TEST("the example") { CHECK_EQ(*fuzzyScore("gt3", "Goto floor 3"), 13); }
TEST("no match") { CHECK(!fuzzyScore("xyz", "Goto floor 3").has_value()); CHECK(!fuzzyScore("3g", "Goto floor 3").has_value()); }
TEST("empty query") { CHECK_EQ(*fuzzyScore("", "anything"), 0); }
TEST("consecutive letters score more") { CHECK(*fuzzyScore("god", "god mode") > *fuzzyScore("gmd", "god mode")); CHECK_EQ(*fuzzyScore("god", "god mode"), 1 + 5 + 1 + 3 + 1 + 3); }
TEST("word starts after separators") { CHECK_EQ(*fuzzyScore("sm", "spawn_monster"), 1 + 5 + 1 + 5); CHECK_EQ(*fuzzyScore("m", "set.monster"), 6); }
TEST("ranking")
{
    const std::vector<std::string> commands{ "Toggle god mode", "Goto floor 3", "Give gold", "Reveal map" };
    CHECK(rank("go", commands) == std::vector<std::string>({ "Goto floor 3", "Give gold", "Toggle god mode" }));
}
TEST("ties keep the original order") { CHECK(rank("a", { "xa", "ya" }) == std::vector<std::string>({ "xa", "ya" })); }

